"""bigcode-evaluation-harness's SantaCoder FIM task (docker/Dockerfile.eval) on this tokenizer, generated by vLLM.

The task is SantaCoderFIM constructed as its StarCoderFIM is for StarCoder's tokens: SantaCoderFIM(fim_prefix,
fim_middle, fim_suffix, stop_words). Its prompt is fim_prefix prefix fim_suffix suffix fim_middle; the packer's PSM
(corpus.tokenizer.fim_prompt, docs/corpus.md §8) is BOS FIM_BEGIN prefix FIM_HOLE suffix FIM_END, so fim_prefix =
FIM_BEGIN, fim_suffix = FIM_HOLE, fim_middle = FIM_END, and the tokenizer's post-processor puts BOS first. The model
ends a middle with BOS, its EOS; the special tokens are the stop words, as the task's own are its tokenizer's.

main.py generates through transformers one problem at a time (33-66 s a problem on the d24 export, mostly middles
that never stop), so vLLM generates here and the task's own code does the rest, as main.py's evaluator does:
the prompt is task.get_prompt's text encoded by the export's tokenizer (BOS first, as main.py's tokenizer call);
greedy (main.py --do_sample False); prompt and middle within MAX_LENGTH tokens (main.py --max_length_generation; its
default 512 truncates 105 of the 1,043 Python prompts under this tokenizer; a prompt that fills it gets an empty
middle, as main.py returns the input); task.postprocess_generation on the prompt and the generated text decoded with
special tokens (bigcode_eval/utils.py update_code_gens, its branch for an EOS among the stop words); then
task.process_results, the exact match of stripped middle and reference per language. Outputs as main.py
--save_generations --save_references writes them.

    python -m eval.official_fim <model dir> <out dir>
"""

import json
import sys
from pathlib import Path

from bigcode_eval.tasks.santacoder_fim import SantaCoderFIM
from vllm import LLM, SamplingParams

from corpus.tokenizer import BOS, FIM_BEGIN, FIM_END, FIM_HOLE, SPECIAL_TOKENS

TASK = "nanochat_fim"
MAX_LENGTH = 2048


def task() -> SantaCoderFIM:
    return SantaCoderFIM(fim_prefix=FIM_BEGIN, fim_middle=FIM_END, fim_suffix=FIM_HOLE,
                         stop_words=[BOS, *(t for t in SPECIAL_TOKENS if t != BOS)])


def main(model: str, out: Path) -> None:
    fim = task()
    rows = fim.get_dataset()
    prompts = [fim.get_prompt(doc) for doc in rows]
    llm = LLM(model, trust_remote_code=True, dtype="bfloat16", max_model_len=MAX_LENGTH)
    ids = [llm.get_tokenizer()(p).input_ids for p in prompts]
    todo = [i for i, x in enumerate(ids) if len(x) < MAX_LENGTH]
    outputs = llm.generate([{"prompt_token_ids": ids[i]} for i in todo],
                           [SamplingParams(temperature=0.0, max_tokens=MAX_LENGTH - len(ids[i]), stop=fim.stop_words,
                                           skip_special_tokens=False) for i in todo])
    middles = dict.fromkeys(range(len(prompts)), "") | {i: o.outputs[0].text for i, o in zip(todo, outputs, strict=True)}
    generations = [[fim.postprocess_generation(prompts[i] + middles[i], i)] for i in range(len(prompts))]
    references = [fim.get_reference(doc) for doc in rows]
    # per row: how the middle ended ("stop": a stop word or BOS; "length": the MAX_LENGTH limit) and its tokens
    ends = dict.fromkeys(range(len(prompts)), {"finish": "prompt_too_long", "new_tokens": 0}) | {
        i: {"finish": o.outputs[0].finish_reason, "new_tokens": len(o.outputs[0].token_ids)}
        for i, o in zip(todo, outputs, strict=True)}
    out.mkdir(parents=True, exist_ok=True)
    (out / f"generations_{TASK}.json").write_text(json.dumps(generations))
    (out / f"references_{TASK}.json").write_text(json.dumps(references))
    (out / f"ends_{TASK}.json").write_text(json.dumps([ends[i] | {"prompt_tokens": len(ids[i])}
                                                       for i in range(len(prompts))]))
    languages = sorted({doc["language"] for doc in rows})
    results = {TASK: fim.process_results(generations, references),
               "config": {"max_length_generation": MAX_LENGTH, "do_sample": False, "n_samples": 1},
               "per_language": {lang: {
                   "rows": sum(doc["language"] == lang for doc in rows),
                   "ended_by_stop": sum(doc["language"] == lang and ends[i]["finish"] == "stop"
                                        for i, doc in enumerate(rows)),
                   "prompts_over_512": sum(doc["language"] == lang and len(ids[i]) > 512 for i, doc in enumerate(rows)),
                   "prompts_over_max_length": sum(doc["language"] == lang and len(ids[i]) >= MAX_LENGTH
                                                  for i, doc in enumerate(rows))} for lang in languages}}
    (out / "evaluation_results.json").write_text(json.dumps(results, indent=2) + "\n")
    print(json.dumps(results, indent=2))


if __name__ == "__main__":
    main(sys.argv[1], Path(sys.argv[2]))
